import styles from "./countdown-block.module.less";
import structure from "@/core/styling/structure.module.less";
import { useEffect, useState, PropsWithChildren } from "react";
import { CallToAction } from "@/core/types/call-to-action-types";
import { PrimaryButtonLink, buttonUrlFromCallToAction } from "@/core/components/primitives/parks-button/parks-button";
import CountdownUnit from "./components/countdown-unit";
import { DateHelper, createDate, multipleClassNames } from "@/core/helpers";
import RichText, { RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import { AnimatePresence, motion } from "framer-motion";
import { GatsbyImage, IGatsbyImageData } from "gatsby-plugin-image";
import { ExistingThemes } from "../../..";

export type ImageField = {
  description?: string;
  gatsbyImageData: IGatsbyImageData;
};

type OverridableCssVariables =
  | "--component-countdown-block-background-color"
  | "--component-countdown-block-text-color"
  | "--component-primary-button-text"
  | "--component-primary-button-background"
  | "--component-primary-button-border";

type ColorOverridesKeys = "backgroundColor" | "textColor" | "buttonTextColor" | "buttonBackgroundColor";

export type ColorOverrides = {
  backgroundColor?: string;
  textColor?: string;
  dayBackgroundColor?: string;
  hourBackgroundColor?: string;
  minuteBackgroundColor?: string;
  secondBackgroundColor?: string;
  dayTextColor?: string;
  hourTextColor?: string;
  minuteTextColor?: string;
  secondTextColor?: string;
  dayLineColor?: string;
  hourLineColor?: string;
  minuteLineColor?: string;
  secondLineColor?: string;
  buttonBackgroundColor?: string;
  buttonTextColor?: string;
};

const overrideMapping: Record<ColorOverridesKeys, Array<OverridableCssVariables>> = {
  backgroundColor: ["--component-countdown-block-background-color"],
  textColor: ["--component-countdown-block-text-color"],
  buttonTextColor: ["--component-primary-button-text"],
  buttonBackgroundColor: ["--component-primary-button-background", "--component-primary-button-border"],
};

const getStyleOverrides = (colorOverrides?: ColorOverrides) => {
  if (!colorOverrides) return {};

  const listOfAllKeysOfColorOverrides = Object.keys(overrideMapping) as Array<ColorOverridesKeys>;

  const styleOverrides = {} as Record<OverridableCssVariables, string>;
  for (const key of listOfAllKeysOfColorOverrides) {
    const overrideValue = colorOverrides[key];
    if (!overrideValue) continue;

    for (const cssVariable of overrideMapping[key]) {
      styleOverrides[cssVariable] = overrideValue;
    }
  }

  return styleOverrides as React.CSSProperties;
};

type CountdownValue = {
  value: string;
  unit: "day" | "hour" | "minute" | "second";
  backgroundOverrideKey:
    | "dayBackgroundColor"
    | "hourBackgroundColor"
    | "minuteBackgroundColor"
    | "secondBackgroundColor";
  textOverrideKey: "dayTextColor" | "hourTextColor" | "minuteTextColor" | "secondTextColor";
  lineOverrideKey: "dayLineColor" | "hourLineColor" | "minuteLineColor" | "secondLineColor";
};

export type CountdownFinishedEffect = "disappear" | "showText";

export type Props = {
  image?: {
    xs: ImageField;
    s: ImageField;
    m: ImageField;
    l: ImageField;
  };
  heading?: string;
  primaryText?: RichTextType;
  secondaryText?: RichTextType;
  callToActionButton?: CallToAction;
  targetDateTimeStockholm: string;
  size?: "xs" | "s" | "m" | "l";
  colorOverrides?: ColorOverrides;
  countdownFinishedEffect?: CountdownFinishedEffect;
  finishedText?: RichTextType;
  contentfulId?: string;
  componentTheme?: ExistingThemes;
  hasBackgroundColor?: boolean;
  withMargin?: boolean;
};

export const CountdownBlock = (props: PropsWithChildren<Props>) => {
  const {
    image,
    heading,
    primaryText,
    secondaryText,
    callToActionButton,
    targetDateTimeStockholm,
    size = "m",
    colorOverrides,
    countdownFinishedEffect = "disappear",
    finishedText,
    contentfulId,
    componentTheme,
    hasBackgroundColor = false,
    withMargin = true,
  } = props;

  const [now, setNow] = useState(createDate());

  useEffect(() => {
    const interval = setInterval(() => setNow(createDate()), 1000);
    return () => clearInterval(interval);
  }, []);

  const targetDateTime = DateHelper.wallTimeToUTCDateTime(targetDateTimeStockholm, "Europe/Stockholm");

  if (!targetDateTime) {
    return null;
  }

  const totalSeconds = DateHelper.durationBetween(targetDateTime, now, "seconds");
  const isFinished = totalSeconds <= 0;
  const days = Math.max(0, DateHelper.durationBetween(targetDateTime, now, "days"));
  const hours = Math.max(0, DateHelper.durationBetween(targetDateTime, now, "hours") % 24);
  const minutes = Math.max(0, DateHelper.durationBetween(targetDateTime, now, "minutes") % 60);
  const seconds = Math.max(0, totalSeconds % 60);

  const countdownValues: CountdownValue[] = [
    {
      value: String(days),
      unit: "day",
      backgroundOverrideKey: "dayBackgroundColor",
      textOverrideKey: "dayTextColor",
      lineOverrideKey: "dayLineColor",
    },
    {
      value: String(hours),
      unit: "hour",
      backgroundOverrideKey: "hourBackgroundColor",
      textOverrideKey: "hourTextColor",
      lineOverrideKey: "hourLineColor",
    },
    {
      value: String(minutes),
      unit: "minute",
      backgroundOverrideKey: "minuteBackgroundColor",
      textOverrideKey: "minuteTextColor",
      lineOverrideKey: "minuteLineColor",
    },
    {
      value: String(seconds),
      unit: "second",
      backgroundOverrideKey: "secondBackgroundColor",
      textOverrideKey: "secondTextColor",
      lineOverrideKey: "secondLineColor",
    },
  ];

  const buttonUrl = buttonUrlFromCallToAction(callToActionButton);

  const styleOverrides = getStyleOverrides(colorOverrides);

  const selectedImageData = getImageData(image, size);

  return (
    <section
      className={multipleClassNames(
        componentTheme,
        withMargin && structure.block,
        withMargin && structure.blockFloating,
      )}
      data-contentful-id={contentfulId}
    >
      <AnimatePresence initial={false}>
        {!isFinished && (
          <motion.div
            key="countdown"
            exit={{ opacity: 0 }}
            initial={{ opacity: 1 }}
            animate={{ opacity: 1 }}
            className={styles.wrapper}
            data-size={size}
            data-has-background-color={hasBackgroundColor}
            style={styleOverrides}
          >
            {selectedImageData && (
              <div className={styles.countdownImageWrapper}>
                <GatsbyImage
                  className={styles.countdownImage}
                  image={selectedImageData.gatsbyImageData}
                  alt={selectedImageData.description || heading || ""}
                  objectFit="contain"
                />
              </div>
            )}

            {(heading || primaryText) && (
              <div className={styles.titleAndPrimaryText}>
                {heading && <h2>{heading}</h2>}
                {primaryText && <RichText richText={primaryText} />}
              </div>
            )}

            <ul>
              {countdownValues.map((countdown, index) => (
                <div key={index}>
                  <CountdownUnit
                    value={countdown.value}
                    unit={countdown.unit}
                    backgroundColor={colorOverrides?.[countdown.backgroundOverrideKey]}
                    textColor={colorOverrides?.[countdown.textOverrideKey]}
                    lineColor={colorOverrides?.[countdown.lineOverrideKey]}
                  />
                </div>
              ))}
            </ul>

            {secondaryText && <RichText richText={secondaryText} />}

            {callToActionButton?.title && buttonUrl && (
              <PrimaryButtonLink
                url={buttonUrl}
                label={callToActionButton.title}
                openInNewTab={callToActionButton.openInNewTab}
              />
            )}
          </motion.div>
        )}
        {isFinished && countdownFinishedEffect === "disappear" && null}
        {isFinished && countdownFinishedEffect === "showText" && (
          <motion.div
            key="showText"
            exit={{ opacity: 0 }}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.5 }}
            className={styles.wrapper}
            data-size={size}
            style={styleOverrides}
          >
            {selectedImageData && (
              <div className={styles.countdownImageWrapper}>
                <GatsbyImage
                  className={styles.countdownImage}
                  image={selectedImageData.gatsbyImageData}
                  alt={selectedImageData.description || heading || ""}
                  objectFit="contain"
                />
              </div>
            )}
            <div className={styles.titleAndPrimaryText}>
              <h2>{finishedText ? <RichText richText={finishedText} /> : heading}</h2>
            </div>
            {callToActionButton?.title && buttonUrl && (
              <PrimaryButtonLink
                url={buttonUrl}
                label={callToActionButton.title}
                openInNewTab={callToActionButton.openInNewTab}
              />
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </section>
  );
};

const getImageData = (image: Props["image"], size: Props["size"]) => {
  if (!image || !size) return undefined;

  switch (size) {
    case "xs":
      return image.xs;
    case "s":
      return image.s;
    case "m":
      return image.m;
    case "l":
      return image.l;
    default:
      return image.m;
  }
};

export default CountdownBlock;
