const createRichText = (text: string): RichTextType => ({
  raw: JSON.stringify({
    nodeType: "document",
    data: {},
    content: [
      {
        nodeType: "paragraph",
        data: {},
        content: [
          {
            nodeType: "text",
            value: text,
            marks: [],
            data: {},
          },
        ],
      },
    ],
  }),
});

const createBoldRichText = (text: string): RichTextType => ({
  raw: JSON.stringify({
    nodeType: "document",
    data: {},
    content: [
      {
        nodeType: "paragraph",
        data: {},
        content: [
          {
            nodeType: "text",
            value: text,
            marks: [{ type: "bold" }],
            data: {},
          },
        ],
      },
    ],
  }),
});

